def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_defects = 0
    my_defects = 0
    last_my = last_opp = 'C'
    opp_streak_d = 0

    for i in range(n):
        m, o = history[i]
        if o == 'D':
            opp_defects += 1
        if m == 'D':
            my_defects += 1
    last_my, last_opp = history[-1]

    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak_d += 1
        else:
            break

    opp_rate = opp_defects / n
    recent_n = n if n < 10 else 10
    recent_opp_def = 0
    for i in range(n - recent_n, n):
        if history[i][1] == 'D':
            recent_opp_def += 1

    if n < 6:
        if last_opp == 'D':
            return 'D'
        return 'C'

    if n > 90:
        if opp_rate <= 0.1:
            if n > 96 and last_opp == 'C':
                return 'D'
            return 'C'
        if opp_rate >= 0.5:
            return 'D'
        if last_opp == 'C' and recent_opp_def == 0:
            return 'C'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if recent_opp_def >= 4:
        return 'D'

    if opp_streak_d >= 3:
        if opp_rate < 0.25:
            return 'C'
        return 'D'

    if recent_opp_def == 0 and last_opp == 'C':
        if n > 20 and opp_rate < 0.05 and n % 31 == 0:
            return 'D'
        return 'C'

    if last_opp == 'C':
        if last_my == 'D':
            if opp_rate > 0.4 or recent_opp_def == 0:
                return 'C'
            return 'C'
        return 'C'

    if last_opp == 'D':
        if n < 20:
            if opp_defects <= max(1, n // 10):
                return 'C'
            return 'D'

        if opp_rate > 0.35:
            return 'D'

        if opp_rate > 0.15:
            recent5_opp_def = 0
            start = n - 5 if n >= 5 else 0
            for i in range(start, n):
                if history[i][1] == 'D':
                    recent5_opp_def += 1
            if recent5_opp_def >= 3:
                return 'D'
            if recent5_opp_def == 1 and n >= 3:
                if history[-2][1] == 'C' and history[-1][1] == 'D':
                    if rng.random() < 0.5:
                        return 'C'
                return 'D'
            return 'D'

        if rng.random() < 0.35:
            return 'C'
        return 'D'

    return 'C'
